    visited = {start}

    while queue:
        (row, col), path = queue.popleft()

        neighbors = [
            (row - 1, col),  # Up
            (row + 1, col),  # Down
            (row, col - 1),  # Left
            (row, col + 1)   # Right
        ]

        for r, c in neighbors:
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                if (r, c) == goal:
                    return path + [(r, c)]

                queue.append(((r, c), path + [(r, c)]))
                visited.add((r, c))

    return []
