    visited = {start}
    parent = {}

    while queue:
        row, col = queue.popleft()

        if (row, col) == goal:
            path = []
            curr = goal
            while curr != start:
                path.append(curr)
                curr = parent[curr]
            path.append(start)
            return path[::-1]

        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for r, c in neighbors:
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                queue.append((r, c))
                visited.add((r, c))
                parent[(r, c)] = (row, col)

    return []
